    def _subsystems_for_event(self, event: SimEvent) -> Set[str]:
        subsystems: Set[str] = set()
        for doc_type in event.artifact_ids or {}:
            s = _ARTIFACT_SUBSYSTEM.get(doc_type, "default")
            if s != "default":
                subsystems.add(s)
        return subsystems

